component.css:
.cha{position:relative;width:100%;aspect-ratio:1672/941;container-type:size;overflow:hidden;background:#050203;font-family:serif;user-select:none}
.cam{position:absolute;inset:0;perspective:42cqh;perspective-origin:50% 52%}
.world{position:absolute;left:50%;top:50%;width:0;height:0;transform-style:preserve-3d}
.w{position:absolute;left:0;top:0;transform-origin:0 0;backface-visibility:hidden}
.tl,.tr{width:800cqh;height:60cqh;background:linear-gradient(180deg,rgba(8,2,3,.95) 0%,rgba(36,13,16,0) 24%,rgba(44,16,18,0) 58%,rgba(5,1,2,.97) 100%),repeating-linear-gradient(90deg,#2b1216 0 3cqh,#1d0c0f 3cqh 30cqh)}
.tl::after,.tr::after{content:"";position:absolute;left:0;top:12%;width:100%;height:.9cqh;background:repeating-linear-gradient(90deg,rgba(255,95,80,.42) 0 1.3cqh,rgba(255,95,80,0) 1.3cqh 30cqh);filter:blur(.25cqh)}
.tf{width:90cqh;height:800cqh;background:repeating-linear-gradient(180deg,#181019 0 3cqh,#0e090d 3cqh 30cqh);box-shadow:inset 0 0 26cqh #000}
.tf::after{content:"";position:absolute;left:49.6%;top:0;width:.8cqh;height:100%;background:rgba(255,120,90,.12)}
.tc{width:90cqh;height:800cqh;background:#0d070a;box-shadow:inset 0 0 26cqh #000}
.tc::after{content:"";position:absolute;left:0;top:49.6%;width:100%;height:.8cqh;background:rgba(255,110,84,.16);filter:blur(.3cqh)}
.ob{position:absolute;left:0;top:0;width:24cqh;height:34cqh;transform-origin:0 0;background:linear-gradient(180deg,rgba(34,24,12,.85),rgba(14,10,8,.92)),repeating-linear-gradient(45deg,rgba(202,166,74,.5) 0 2.2cqh,rgba(23,18,29,0) 2.2cqh 4.4cqh);border:.4cqh solid rgba(202,166,74,.5);box-shadow:0 0 3cqh rgba(0,0,0,.75)}
.chexit{position:absolute;width:90cqh;height:60cqh;background:radial-gradient(ellipse at 50% 62%,#fff,#ffe3b0 32%,#8a5a20 54%,#160b04 78%);box-shadow:0 0 18cqh 4cqh rgba(255,235,190,.5)}
.vig{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 52%,transparent 36%,rgba(0,0,0,.85) 100%)}
.chred{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at 50% 52%,transparent 42%,rgba(255,26,16,.6) 100%);opacity:0}
.mflick{position:absolute;inset:0;pointer-events:none;background:url(https://origin.picgo.net/2026/10/24/10000864301b96798a71a4006d.jpg) center 30% no-repeat;background-size:58% auto;opacity:0;filter:contrast(1.5) brightness(.72) saturate(1.2);mix-blend-mode:screen;transition:opacity .14s}
.bar{position:absolute;top:0;left:0;right:0;height:.6cqh;background:rgba(255,255,255,.07)}
.bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#7ce8c8,#fff)}
.whisper{position:absolute;left:0;right:0;top:10%;text-align:center;color:#d99c92;font-size:3.8cqh;letter-spacing:.4em;text-shadow:0 0 2.4cqh rgba(255,80,60,.45);opacity:0;transition:opacity .8s;pointer-events:none}
.whisper.is-on{opacity:.9}
.mir{position:absolute;left:50%;top:3%;transform:translateX(-50%);width:15%;border:.35cqh solid #6a5a4a;border-radius:.9cqh;box-shadow:0 .4cqh 1.8cqh rgba(0,0,0,.8);background:#0a0708;z-index:3}
.mir span{display:block;text-align:center;font-size:1.3cqh;color:#8a7a6a;letter-spacing:.4em;padding:.25cqh 0}
.mir__m{width:100%;aspect-ratio:4/3;overflow:hidden;position:relative;background:#050304}
.mir__m img{position:absolute;left:50%;top:50%;width:132%;transform:translate(-50%,-50%);object-fit:cover}
.pad{position:absolute;left:2.5%;bottom:6%;width:12%;height:17%;background:rgba(26,12,10,.5);border:1px solid rgba(255,130,100,.3);border-radius:2cqh;color:#e8a08c;font-size:6cqh;cursor:pointer;touch-action:none;z-index:3}
.pad--r{left:auto;right:2.5%}
.pad:active{background:rgba(140,40,25,.55)}
.mscare{position:absolute;inset:0;background:url(https://origin.picgo.net/2026/10/24/10000864301b96798a71a4006d.jpg) center no-repeat;background-size:cover;opacity:0;transform:scale(1.5);transition:opacity .15s,transform .55s;pointer-events:none;filter:contrast(1.6) brightness(.85);z-index:8}
.mscare.is-on{opacity:1;transform:scale(1.06)}
.chflash{position:absolute;inset:0;background:#fff;opacity:0;pointer-events:none;transition:opacity 1s;z-index:7}
.endveil{position:absolute;inset:0;background:#000;display:none;z-index:9}
.endveil video{width:100%;height:100%;object-fit:contain}
.trueend{position:absolute;inset:0;display:none;flex-direction:column;justify-content:center;align-items:center;gap:2.2cqh;background:#000}
.trueend b{color:#e8e6df;font-size:7cqh;letter-spacing:.6em;text-shadow:0 0 3cqh rgba(140,220,200,.5);font-weight:400}
.trueend span{color:#8fa3bf;font-size:2.4cqh;letter-spacing:.32em}
.cha.is-shake .cam{animation:cshk .3s linear}
@keyframes cshk{20%{transform:translate(1.6cqh,-.8cqh)}45%{transform:translate(-1.3cqh,.6cqh)}70%{transform:translate(.9cqh,1.1cqh)}}

component.script:
"use strict";(() => {
var D = String.fromCharCode(36);
var SL = String.fromCharCode(47);
var root = document.getElementById("chaRoot");
if (!root) return;
var q = s => root.querySelector(s);
var world = q("#chWorld"), exitEl = q("#chExit"), red = q("#chRed"), flick = q("#chFlick");
var bar = q("#chBar"), wh = q("#chWhisper"), mon = q("#chMon"), scare = q("#chScare");
var flash = q("#chFlash"), veil = q("#chEnd"), vid = q("#chVid"), card = q("#chTrue");
var ENDTXT = "<EndChat>" + "𝑼𝒏𝒅𝒆𝒓𝒘𝒉𝒆𝒍𝒎𝒆𝒅 𝒃𝒚 𝒕𝒉𝒆 𝒂𝒎𝒃𝒊𝒈𝒖𝒊𝒕𝒚" + "<" + SL + "EndChat>";
var p = 0, m = 30, px = 0, tl = 0, gone = false, seen = false;
var stmbUntil = 0, lungeUntil = 0, nextLunge = 15000, nextBeat = 0, whT = 0;
var D_EXIT = 1150, last = 0;
var clamp = (v, a, b) => v < a ? a : v > b ? b : v;
var whisper = t => {
  wh.textContent = t;
  wh.classList.add("is-on");
  clearTimeout(whT);
  whT = setTimeout(() => wh.classList.remove("is-on"), 3200);
};
var AC = null, master = null, bgm = null, nz = null, nextNote = 0, step = 0;
var audio = () => {
  if (AC) { try { AC.resume(); } catch (e) {} return; }
  try { AC = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) { return; }
  master = AC.createGain(); master.gain.value = 0.85; master.connect(AC.destination);
  if (!nz) { nz = AC.createBuffer(1, 11162, AC.sampleRate); var ch = nz.getChannelData(0); var i = 0; while (i < ch.length) { ch[i] = (Math.random() * 2 - 1) * 0.8; i++; } }
  nextNote = AC.currentTime + 0.1;
  bgm = setInterval(() => {
    if (!AC || gone) return;
    while (nextNote < AC.currentTime + 0.3) {
      var t = nextNote, f = [55, 55, 58.27, 49][Math.floor(step * 0.25) % 4];
      var o = AC.createOscillator(); o.type = "square"; o.frequency.value = f;
      var lp2 = AC.createBiquadFilter(); lp2.type = "lowpass"; lp2.frequency.value = 340;
      var g = AC.createGain();
      g.gain.setValueAtTime(0.09, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.18);
      o.connect(lp2); lp2.connect(g); g.connect(master);
      o.start(t); o.stop(t + 0.2);
      if (step % 2 === 0) {
        var s2 = AC.createBufferSource(); s2.buffer = nz;
        var hp = AC.createBiquadFilter(); hp.type = "highpass"; hp.frequency.value = 5200;
        var g2 = AC.createGain();
        g2.gain.setValueAtTime(0.05, t); g2.gain.exponentialRampToValueAtTime(0.001, t + 0.05);
        s2.connect(hp); hp.connect(g2); g2.connect(master);
        s2.start(t); s2.stop(t + 0.06);
      }
      if (step % 16 === 14) {
        [466.16, 493.88].forEach(fr => {
          var o3 = AC.createOscillator(); o3.type = "sawtooth"; o3.frequency.value = fr;
          var g3 = AC.createGain();
          g3.gain.setValueAtTime(0.001, t); g3.gain.exponentialRampToValueAtTime(0.055, t + 0.03);
          g3.gain.exponentialRampToValueAtTime(0.001, t + 0.34);
          o3.connect(g3); g3.connect(master);
          o3.start(t); o3.stop(t + 0.36);
        });
      }
      if (step % 4 === 0) {
        var o4 = AC.createOscillator(); o4.type = "sine";
        o4.frequency.setValueAtTime(64, t); o4.frequency.exponentialRampToValueAtTime(34, t + 0.1);
        var g4 = AC.createGain();
        g4.gain.setValueAtTime(0.22, t); g4.gain.exponentialRampToValueAtTime(0.001, t + 0.13);
        o4.connect(g4); g4.connect(master);
        o4.start(t); o4.stop(t + 0.15);
      }
      nextNote += 0.205;
      step++;
    }
  }, 110);
};
var thump = (vol) => {
  if (!AC) return;
  var mk2 = (dl, vv) => {
    var o = AC.createOscillator(); o.type = "sine";
    var t = AC.currentTime + dl;
    o.frequency.setValueAtTime(58, t); o.frequency.exponentialRampToValueAtTime(30, t + 0.16);
    var g = AC.createGain();
    g.gain.setValueAtTime(vv, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.2);
    o.connect(g); g.connect(master);
    o.start(t); o.stop(t + 0.22);
  };
  mk2(0, vol); mk2(0.19, vol * 0.55);
};
var stopBgm = () => { if (bgm) { clearInterval(bgm); bgm = null; } if (master) { try { master.gain.setTargetAtTime(0, AC.currentTime, 0.2); } catch (e) {} } };
var TIL = 5, TLN = 80, tiles = [];
for (var i = 0; i < TIL; i++) {
  ["tl", "tr", "tf", "tc"].forEach(ty => {
    var el = document.createElement("div");
    el.className = "w " + ty;
    world.appendChild(el);
    tiles.push(el);
  });
}
var placeTiles = () => {
  var base = Math.floor((p - 80) * 0.0125);
  for (var j = 0; j < TIL; j++) {
    var a = (base + j) * TLN, z0 = -a * 10, z1 = -(a + TLN) * 10;
    tiles[j * 4].style.transform = "translate3d(-45cqh,-30cqh," + z0 + "cqh) rotateY(90deg)";
    tiles[j * 4 + 1].style.transform = "translate3d(45cqh,-30cqh," + z1 + "cqh) rotateY(-90deg)";
    tiles[j * 4 + 2].style.transform = "translate3d(-45cqh,30cqh," + z1 + "cqh) rotateX(90deg)";
    tiles[j * 4 + 3].style.transform = "translate3d(-45cqh,-30cqh," + z0 + "cqh) rotateX(-90deg)";
  }
};
var obs = [], od = 55;
while (od < 1115) {
  var ln = Math.floor(Math.random() * 3);
  obs.push({ at: od, lane: ln, hit: false });
  if (Math.random() < 0.3) obs.push({ at: od, lane: (ln + 1 + Math.floor(Math.random() * 2)) % 3, hit: false });
  od += 26 + Math.random() * 20;
}
var pool = [];
for (i = 0; i < 10; i++) {
  var ob = document.createElement("div");
  ob.className = "ob";
  world.appendChild(ob);
  pool.push(ob);
}
var drawObs = () => {
  var k = 0;
  for (var j = 0; j < obs.length; j++) {
    var o = obs[j], dAhead = o.at - p;
    if (dAhead > -6 && dAhead < 300 && k < 10) {
      pool[k].style.display = "block";
      pool[k].style.transform = "translate3d(" + (o.lane * 30 - 42) + "cqh,-4cqh," + (-dAhead * 10) + "cqh)";
      pool[k].style.opacity = o.hit ? "0.25" : "1";
      k++;
    }
  }
  for (; k < 10; k++) pool[k].style.display = "none";
};
var stumble = now => {
  stmbUntil = now + 1400;
  m = Math.max(2.4, m - 12);
  thump(0.5);
  root.classList.remove("is-shake"); void root.offsetWidth; root.classList.add("is-shake");
  red.style.transition = "none"; red.style.opacity = "0.55";
  setTimeout(() => { red.style.transition = "opacity .9s"; red.style.opacity = ""; }, 90);
  whisper("别停下！");
};
var caught = () => {
  if (gone) return;
  gone = true;
  stopBgm();
  thump(0.7);
  scare.classList.add("is-on");
  setTimeout(() => {
    try { if (typeof changeMsg === "function") changeMsg(ENDTXT); } catch (e) {}
  }, 1300);
};
var showCard = () => {
  if (card.style.display === "flex") return;
  card.style.display = "flex";
  vid.style.display = "none";
  if (AC) { try { master.gain.setTargetAtTime(0, AC.currentTime, 0.3); } catch (e) {} }
};
var succeed = () => {
  if (gone) return;
  gone = true;
  stopBgm();
  flash.style.opacity = "1";
  setTimeout(() => {
    veil.style.display = "block";
    vid.muted = false;
    var pr = vid.play();
    if (pr && pr.catch) pr.catch(() => { vid.muted = true; vid.play().catch(() => showCard()); });
  }, 1000);
  vid.addEventListener("ended", showCard);
  vid.addEventListener("error", showCard);
  setTimeout(showCard, 40000);
};
document.addEventListener("keydown", e => {
  audio();
  if (e.code === "KeyA" || e.code === "ArrowLeft") { e.preventDefault(); tl = clamp(tl - 1, -1, 1); }
  else if (e.code === "KeyD" || e.code === "ArrowRight") { e.preventDefault(); tl = clamp(tl + 1, -1, 1); }
});
root.querySelectorAll(".pad").forEach(el => {
  el.addEventListener("pointerdown", e => {
    e.preventDefault();
    audio();
    tl = clamp(tl + parseInt(el.dataset.l, 10), -1, 1);
  });
});
var frame = now => {
  if (gone) return;
  var t = now, dt = Math.min(0.05, (now - last) * 0.001); last = now;
  var stmb = t < stmbUntil;
  var v = stmb ? 2 : 8 + Math.min(1.2, p * 0.001);
  p += v * dt;
  var dx = tl * 30 - px;
  px += clamp(dx, -dt * 260, dt * 260);
  var lunging = t < lungeUntil;
  m += (lunging ? -2.4 : (stmb ? v - 6.8 : (m > 36 ? -0.9 : 0.3))) * dt;
  if (t > nextLunge && !stmb && m > 12) {
    lungeUntil = t + 5000;
    nextLunge = t + 20000 + Math.random() * 12000;
    thump(0.6);
    flick.style.opacity = "0.55";
    setTimeout(() => { flick.style.opacity = "0"; }, 170);
    setTimeout(() => { flick.style.opacity = "0.4"; }, 380);
    setTimeout(() => { flick.style.opacity = "0"; }, 620);
  }
  for (var j = 0; j < obs.length; j++) {
    var o = obs[j], da = o.at - p;
    if (!o.hit && da < 1.4 && da > -1.4 && Math.abs(px - (o.lane - 1) * 30) < 17) {
      o.hit = true;
      stumble(t);
    }
  }
  if (m <= 2) { caught(); return; }
  if (t >= nextBeat) {
    thump(clamp(0.16 + (26 - m) * 0.02, 0.16, 0.5));
    nextBeat = t + 170 + m * 15;
  }
  if (D_EXIT - p < 95) {
    exitEl.style.display = "block";
    exitEl.style.transform = "translate3d(-45cqh,-30cqh," + (-(D_EXIT - p) * 10) + "cqh)";
    if (!seen) { seen = true; whisper("出口——！"); }
  }
  if (!lunging && !stmb) red.style.opacity = clamp((26 - m) * 0.045, 0, 0.75).toFixed(2);
  var s = clamp(46 * m ** -1, 0.35, 3.2);
  mon.style.transform = "translate(-50%," + (-50 + (Math.random() * 4 - 2)).toFixed(1) + "%) scale(" + s.toFixed(2) + ")";
  mon.style.filter = "brightness(" + Math.min(1.2, 0.25 + 12 * m ** -1).toFixed(2) + ")";
  world.style.transform = "translate3d(" + (-px).toFixed(1) + "cqh," + (stmb ? Math.sin(t * 0.05) * 0.7 : 0).toFixed(2) + "cqh," + (p * 10).toFixed(1) + "cqh)";
  placeTiles();
  drawObs();
  bar.style.width = clamp(p * 100 * D_EXIT ** -1, 0, 100).toFixed(1) + "%";
  if (p >= D_EXIT - 1.5) { succeed(); return; }
  requestAnimationFrame(frame);
};
whisper("跑！！");
audio();
last = performance.now();
requestAnimationFrame(frame);
})();
